package android.content;import android.database.ContentObserver;import android.net.Uri;import java.util.*;public class ContentResolver {public final Map<String,String> settings=new HashMap<>();public final Set<ContentObserver> observers=new HashSet<>();public void registerContentObserver(Uri u,boolean d,ContentObserver o){observers.add(o);}public void unregisterContentObserver(ContentObserver o){observers.remove(o);}public void change(){for(ContentObserver o:new ArrayList<>(observers))o.onChange(false);}}